def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    if n <= 2:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    exploit = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'D' and o == 'C':
            exploit += 1

    opp_d = n - opp_c

    rec_len = 10 if n >= 10 else n
    recent = history[-rec_len:]
    recent_opp_d = 0
    recent_sucker = 0
    recent_exploit = 0
    for m, o in recent:
        if o == 'D':
            recent_opp_d += 1
        if m == 'C' and o == 'D':
            recent_sucker += 1
        if m == 'D' and o == 'C':
            recent_exploit += 1
    recent_opp_c = rec_len - recent_opp_d

    trail = 0
    for m, o in reversed(history):
        if m == my_last and o == opp_last:
            trail += 1
        else:
            break

    prev_m, prev_o = history[-2]

    attempts = 0
    for i in range(1, n):
        m, o = history[i]
        pm, po = history[i - 1]
        if m == 'C' and o == 'D' and pm == 'D' and po == 'D':
            attempts += 1

    if n >= 95 and opp_last == 'C' and recent_sucker == 0 and recent_exploit >= 3 and opp_c >= opp_d + 8:
        return 'D'

    if n == 98 and opp_last == 'C' and exploit >= 2 and recent_sucker == 0 and opp_c >= opp_d + 10:
        return 'D'

    if opp_d == 0:
        if exploit >= 2:
            return 'D'
        if exploit == 1 and n < 90:
            return 'D'
        if exploit == 0 and rng.random() < 0.03:
            return 'D'
        return 'C'

    if exploit >= 4 and recent_exploit >= 3 and recent_sucker <= 1 and opp_d <= 6:
        return 'D' if opp_last == 'C' else 'C'

    if my_last == 'C' and opp_last == 'D' and prev_m == 'D' and prev_o == 'D':
        return 'C'

    if my_last == 'D' and opp_last == 'D':
        if trail >= 2 and recent_opp_c >= 3 and opp_c >= opp_d + 6:
            return 'C'
        if trail >= 3 and attempts == 0 and n < 40:
            return 'C'
        return 'D'

    if my_last == 'C' and opp_last == 'D':
        if trail >= 2 and attempts > 0:
            return 'D'
        if trail == 1 and recent_opp_d >= 2 and recent_opp_c >= 2 and recent_exploit >= 2 and opp_c >= opp_d - 3:
            return 'C'
        if opp_c >= opp_d + 6 and recent_opp_c >= 3 and recent_opp_d <= 4:
            return 'C' if rng.random() < 0.25 else 'D'
        return 'D'

    if my_last == 'D' and opp_last == 'C':
        if exploit >= 2 and recent_sucker == 0 and opp_d <= opp_c and rng.random() < 0.5:
            return 'D'
        if opp_c >= opp_d + 10 and recent_opp_c >= 8 and trail >= 2:
            return 'D'
        return 'C'

    if opp_c >= opp_d + 8 and recent_opp_c >= 9 and n > 30 and rng.random() < 0.03:
        return 'D'
    return 'C'
